import React, { useState } from 'react';
import { Search, Globe, ChevronDown } from 'lucide-react';

const LanguageSelector = ({ languages, selectedLang, onSelectLanguage }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [search, setSearch] = useState('');

  const langList = Object.entries(languages || {}).map(([code, meta]) => ({
    code,
    ...meta
  }));

  const filtered = langList.filter(l => 
    l.name.toLowerCase().includes(search.toLowerCase()) ||
    l.native.toLowerCase().includes(search.toLowerCase()) ||
    l.code.toLowerCase().includes(search.toLowerCase())
  );

  const currentMeta = languages[selectedLang] || { name: 'Select Language', flag: '🌐', native: '' };

  return (
    <div style={{ position: 'relative', width: '260px' }}>
      <button 
        onClick={() => setIsOpen(!isOpen)}
        className="glass-panel"
        style={{
          width: '100%',
          display: 'flex',
          alignItems: 'center',
          justify: 'space-between',
          padding: '10px 16px',
          color: '#fff',
          cursor: 'pointer',
          border: '1px solid rgba(255, 255, 255, 0.15)',
          background: 'rgba(18, 22, 41, 0.8)'
        }}
      >
        <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
          <span style={{ fontSize: '20px' }}>{currentMeta.flag}</span>
          <div style={{ textAlign: 'left' }}>
            <div style={{ fontWeight: 600, fontSize: '14px' }}>{currentMeta.name}</div>
            <div style={{ fontSize: '11px', color: '#94a3b8' }}>{currentMeta.native}</div>
          </div>
        </div>
        <ChevronDown size={18} color="#94a3b8" />
      </button>

      {isOpen && (
        <div 
          className="glass-panel"
          style={{
            position: 'absolute',
            top: '55px',
            left: 0,
            width: '100%',
            maxHeight: '320px',
            overflowY: 'auto',
            zIndex: 100,
            padding: '10px',
            background: 'rgba(15, 23, 42, 0.95)'
          }}
        >
          <div style={{ display: 'flex', alignItems: 'center', gap: '8px', padding: '6px 10px', background: 'rgba(255, 255, 255, 0.05)', borderRadius: '8px', marginBottom: '10px' }}>
            <Search size={14} color="#94a3b8" />
            <input 
              type="text" 
              placeholder="Search 51 languages..." 
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              style={{
                background: 'transparent',
                border: 'none',
                color: '#fff',
                outline: 'none',
                width: '100%',
                fontSize: '13px'
              }}
            />
          </div>

          {filtered.length === 0 ? (
            <div style={{ padding: '10px', fontSize: '12px', color: '#94a3b8', textAlign: 'center' }}>No language found</div>
          ) : (
            filtered.map((l) => (
              <div 
                key={l.code}
                onClick={() => {
                  onSelectLanguage(l.code);
                  setIsOpen(false);
                }}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  justify: 'space-between',
                  padding: '8px 10px',
                  borderRadius: '8px',
                  cursor: 'pointer',
                  background: selectedLang === l.code ? 'rgba(139, 92, 246, 0.25)' : 'transparent',
                  transition: 'background 0.2s'
                }}
              >
                <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                  <span style={{ fontSize: '18px' }}>{l.flag}</span>
                  <div>
                    <div style={{ fontSize: '13px', fontWeight: 500, color: '#fff' }}>{l.name}</div>
                    <div style={{ fontSize: '11px', color: '#94a3b8' }}>{l.native}</div>
                  </div>
                </div>
                {l.dir === 'rtl' && <span className="badge-tag" style={{ fontSize: '10px', padding: '2px 6px' }}>RTL</span>}
              </div>
            ))
          )}
        </div>
      )}
    </div>
  );
};

export default LanguageSelector;
